data-dialog.apiDescription:
## Models

Two-way bindings. Bind each one with the `v-model` syntax shown next to it — do not pass the prop and listen to its `update:` event separately.

```
export type dialogModels = {
  /** @description visibility of Dialog */
  modelValue?: boolean; // v-model="..."
}
```

## Props

```
export type dialogProps = {
  /**
   * @description set overflow
   * @default true
   */
  overflow?: boolean;
  /**
   * @description control the body element overflow
   * @default false
   */
  alignCenter?: boolean;
  /** @description size mode for dialog width */
  sizeMode?: string;
  /**
   * @description title of Dialog
   * @default ''
   */
  title?: string;
  /**
   * @description whether the Dialog displays a close button
   * @default true
   */
  showClose?: boolean;
  /**
   * @description header's aria-level attribute
   * @default '2'
   */
  ariaLevel?: string;
  /**
   * @description buttons to show in footer
   * @default []
   */
  footerButtons?: FooterButton[];
  /** @description whether Dialog takes up full screen */
  fullscreen?: boolean;
  /** @description whether Dialog can be dragged */
  draggable?: boolean;
  /**
   * @description whether to append Dialog itself to body. A nested Dialog should have this attribute set to `true`
   * @default false
   */
  appendToBody?: boolean;
  /**
   * *
   *
   * @description which element the Dialog appends to
   * @default 'body'
   */
  appendTo?: string | HTMLElement;
  /**
   * @description destroy elements in Dialog when closed
   * @default false
   */
  destroyOnClose?: boolean;
  /**
   * @description whether the Dialog can be closed by clicking the mask
   * @default true
   */
  closeOnClickModal?: boolean;
  /**
   * @description whether the Dialog can be closed by pressing ESC
   * @default true
   */
  closeOnPressEscape?: boolean;
  /**
   * @description whether scroll of body is disabled while Dialog is displayed
   * @default true
   */
  lockScroll?: boolean;
  /**
   * @description whether a mask is displayed
   * @default true
   */
  modal?: boolean;
  /**
   * @description the Time(milliseconds) before open
   * @default 0
   */
  openDelay?: number;
  /**
   * @description the Time(milliseconds) before close
   * @default 0
   */
  closeDelay?: number;
  /**
   * @description Whether to trap focus inside the dialog
   * @default true
   */
  trapFocus?: boolean;
  /** @description width of Dialog, default is 50% */
  width?: string | number;
  /** @description custom class names for header wrapper */
  headerClass?: string;
  /** @description custom class names for body wrapper */
  bodyClass?: string;
  /** @description custom class names for footer wrapper */
  footerClass?: string;
  /** @description callback before Dialog closes, and it will prevent Dialog from closing, use done to close the dialog */
  beforeClose?: DialogBeforeCloseFn;
  /** @description value for `margin-top` of Dialog CSS, default is 15vh */
  top?: string;
  /** @description same as z-index in native CSS, z-order of dialog */
  zIndex?: number;
  /** @description custom class names for mask */
  modalClass?: string;
}
```

## Events

```
export type dialogEvents = {
  "update:modelValue": [value: boolean];
  open: [];
  opened: [];
  close: [];
  closed: [];
  openAutoFocus: [];
  closeAutoFocus: [];
}
```

## Slots

Each slot is typed with the props it passes to its content.

```
export type dialogSlots = {
  header: {};
  image: {};
  default: {};
  footer: {};
}
```

## Exposed

Available on the component instance through a template ref.

```
export type dialogExposed = {
  /** @description whether the dialog is visible */
  visible: boolean;
  dialogContentRef: any;
  resetPosition: () => void;
}
```
